chain:
async (req, res) => {
  const isSse = req.headers.accept?.includes("text/event-stream");
  const conversationId = req.params.conversationId;
  const { prompt, modelId } = req.body || {};
  const actorId = req.session?.principalId || null;

  if (isSse) {
    let headersSent = false;
    try {
      // Pre-validate before writing SSE headers
      if (!prompt || typeof prompt !== "string" || !prompt.trim()) {
        return sendProblem(req, res, 400, "Prompt must not be empty");
      }

      res.writeHead(200, {
        "Content-Type": "text/event-stream",
        "Cache-Control": "no-cache",
        "Connection": "keep-alive",
        "X-Accel-Buffering": "no",
      });
      headersSent = true;

      const result = await ProviderService.executeTurn({
        conversationId,
        prompt,
        modelId,
        actorId,
        onToken: (token) => {
          res.write(`data: ${JSON.stringify({ type: "token", token })}\n\n`);
        },
      });

      res.write(`data: ${JSON.stringify({ type: "done", ...result })}\n\n`);
      return res.end();
    } catch (err) {
      if (!headersSent) {
        return handleError(req, res, err);
      }
      res.write(
        `data: ${JSON.stringify({
          type: "error",
          error: err.message,
          code: err.code || "TURN_FAILED",
        })}\n\n`
      );
      return res.end();
    }
  }

  // Standard JSON response
  try {
    const collectedTokens = [];
    const result = await ProviderService.executeTurn({
      conversationId,
      prompt,
      modelId,
      actorId,
      onToken: (token) => {
        collectedTokens.push(token);
      },
    });

    return res.status(200).json({
      data: {
        ...result,
        tokens: collectedTokens,
      },
      meta: { requestId: req.requestId },
    });
  } catch (err) {
    return handleError(req, res, err);
  }
}

