chain:
async (req, res) => {
  const runId = req.params.runId;
  const cursorParam = req.headers["last-event-id"] || req.query.after;

  let afterSeq = 0;
  if (cursorParam !== undefined) {
    const parsed = Number(cursorParam);
    if (Number.isNaN(parsed) || parsed < 0) {
      return sendProblem(req, res, 410, "Event cursor is invalid or expired");
    }
    afterSeq = parsed;
  }

  try {
    // Verify run exists
    await ExecutionService.getRunById(runId);
  } catch (err) {
    return handleError(req, res, err);
  }

  res.writeHead(200, {
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache",
    "Connection": "keep-alive",
    "X-Accel-Buffering": "no",
  });

  // Replay existing events
  const events = await ExecutionService.getRunEvents(runId, { afterSequence: afterSeq, limit: 100 });
  for (const evt of events) {
    res.write(`id: ${evt.sequence}\nevent: ${evt.eventType}\ndata: ${JSON.stringify(evt.payload)}\n\n`);
  }

  // Heartbeat interval
  const timer = setInterval(() => {
    res.write(": ping\n\n");
  }, 15000);

  req.on("close", () => {
    clearInterval(timer);
  });
}

